-- nvim.lua of the {{ theme }} theme. GENERATED by `theme` from
-- ~/dotfiles/theme/templates/nvim.lua; edit that and run `theme apply`.
-- Loaded by ~/.config/nvim/init.lua. The built-in "quiet" scheme in the theme's
-- colours: selection in the accent, love and gold only for errors and warnings.
vim.o.termguicolors = true
vim.o.background = "{{ "dark" if dark else "light" }}"
vim.cmd.colorscheme("quiet")
vim.api.nvim_set_hl(0, "Normal",     { fg = "{{ text }}", bg = "{{ bg }}" })
vim.api.nvim_set_hl(0, "Comment",    { fg = "{{ tone(0x80) }}", italic = true })
vim.api.nvim_set_hl(0, "Visual",     { fg = "{{ on_accent }}", bg = "{{ accent }}" })
vim.api.nvim_set_hl(0, "ErrorMsg",   { fg = "{{ love }}" })
vim.api.nvim_set_hl(0, "WarningMsg", { fg = "{{ gold }}" })
